from typing import List

def min_cost_to_gather_jury_members(n: int, m: int, k: int, flights: List[List[int]]) -> int:
    # Build adjacency list for flights
    graph = defaultdict(list)
    reverse_graph = defaultdict(list)

    for d, f, t, c in flights:
        if f == 0:
            reverse_graph[t].append((d, c))
        elif t == 0:
            graph[f].append((d, c))

    def dijkstra(graph, start):
        heap = [(0, start)]
        dist = {node: float('inf') for node in graph}
        dist[start] = 0

        while heap:
            current_cost, node = heapq.heappop(heap)

            if current_cost > dist[node]:
                continue

            for neighbor, weight in graph[node]:
                new_cost = current_cost + weight

                if new_cost < dist[neighbor]:
                    dist[neighbor] = new_cost
                    heapq.heappush(heap, (new_cost, neighbor))

        return dist

    # Find the minimum cost to fly to Metropolis from each city
    metropolis_costs = dijkstra(reverse_graph, 0)

    # Calculate the maximum cost to gather all jury members in Metropolis within k days
    max_cost = 0
    for i in range(1, n + 1):
        cost_to_metropolis = metropolis_costs[i]
        if cost_to_metropolis + metropolis_costs[i] <= k * 2:
            max_cost = max(max_cost, cost_to_metropolis + metropolis_costs[i])
        else:
            return -1

    # Calculate the minimum cost to gather all jury members in Metropolis within k days
    min_cost = float('inf')
    for i in range(1, n + 1):
        cost_to_metropolis = metropolis_costs[i]
        if cost_to_metropolis + metropolis_costs[i] <= k * 2:
            min_cost = min(min_cost, cost_to_metropolis + metropolis_costs[i])
        else:
            return -1

    # Calculate the minimum cost to send all jury members back to their home cities
    for i in range(1, n + 1):
        cost_to_home = metropolis_costs[i]
        min_cost += cost_to_home

    return min_cost

