def min_cost_to_gather_jury(n: int, m: int, k: int, flights: List[List[int]]) -> int:
    graph = [[] for _ in range(n + 1)]
    for d, f, t, c in flights:
        if f == 0:
            graph[t].append((d, c))
        elif t == 0:
            graph[f].append((d, c))

    def dijkstra(start: int, end: int, max_days: int) -> int:
        dist = [float('inf')] * (max_days + 1)
        dist[0] = 0
        pq = [(0, start, 0)]

        while pq:
            current_dist, u, day = heapq.heappop(pq)
            if current_dist > dist[day]:
                continue

            for v, weight in graph[u]:
                next_day = v
                new_cost = current_dist + weight

                if next_day <= max_days and new_cost < dist[next_day]:
                    dist[next_day] = new_cost
                    heapq.heappush(pq, (new_cost, v, next_day))

        return dist[end]

    min_cost = float('inf')
    for d, _, t, _ in flights:
        if t == 0:
            cost = dijkstra(t, d, k)
            if cost != float('inf'):
                min_cost = min(min_cost, cost)

    return -1 if min_cost == float('inf') else min_cost

