from sys import stdin, stdout

def min_cost_to_gather_jury(n, m, k):
    graph = [[] for _ in range(n + 1)]

    for _ in range(m):
        d, f, t, c = map(int, stdin.readline().split())
        if f == 0:
            graph[t].append((d, c))
        elif t == 0:
            graph[f].append((d, c))

    def dijkstra(start, end):
        pq = [(0, start)]
        distances = [float('inf')] * (n + 1)
        distances[start] = 0

        while pq:
            current_distance, u = heapq.heappop(pq)
            if u == end:
                return current_distance

            for v, weight in graph[u]:
                distance = current_distance + weight

                if distance < distances[v]:
                    distances[v] = distance
                    heapq.heappush(pq, (distance, v))

        return float('inf')

    max_arrival_day = -float('inf')
    for i in range(1, n + 1):
        arrival_day = dijkstra(i, 0) + k
        if arrival_day >= max_arrival_day:
            max_arrival_day = arrival_day

    departure_costs = []
    for i in range(1, n + 1):
        departure_cost = dijkstra(0, i)
        if departure_cost != float('inf'):
            departure_costs.append(departure_cost)

    if not departure_costs or max_arrival_day == -float('inf'):
        return -1

    return sum(departure_costs[-len(departure_costs):])

