import heapq
from collections import defaultdict
from sys import stdin, stdout

def min_cost_gathering_flights(n, m, k):
    flights = defaultdict(list)

    # Parse input flights
    for _ in range(m):
        d, f, t, c = map(int, stdin.readline().strip().split())
        flights[f].append((d, c))
        flights[t].append((d, c))

    # Priority queue for Dijkstra's algorithm
    pq = []
    dist = defaultdict(lambda: float('inf'))
    dist[0] = 0

    for f, flights_from_f in flights.items():
        for d, c in flights_from_f:
            if d == 0:
                dist[f] = min(dist[f], c)

    for d in range(1, k + 1):
        new_dist = dist.copy()
        for f, flights_from_f in flights.items():
            for d_, c in flights_from_f:
                if d_ == d:
                    new_dist[f] = min(new_dist[f], dist[d_] + c)
        dist = new_dist

    result = sum(dist.values())

    return result if result < float('inf') else -1

if __name__ == "__main__":
    n, m, k = map(int, stdin.readline().strip().split())
    stdout.write(str(min_cost_gathering_flights(n, m, k)) + '\n')
